 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors || config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const width = 2.2;
  const height = width / (512 / 320);
  const depth = 0.08;
  const frontZ = depth / 2 + 0.002;

  const root = new Group();
  const floatGroup = new Group();
  root.add(floatGroup);

  const backingGeo = new BoxGeometry(width + 0.06, height + 0.06, depth);
  const backingMat = new MeshBasicNodeMaterial({ color: colors.surface });
  const backing = new Mesh(backingGeo, backingMat);
  floatGroup.add(backing);

  const picGeo = new PlaneGeometry(width, height);
  const picMat = new MeshBasicNodeMaterial({ color: colors.paper });
  const pic = new Mesh(picGeo, picMat);
  pic.position.z = frontZ;
  floatGroup.add(pic);

  const stripHeight = 0.32;
  const stripGeo = new PlaneGeometry(width - 0.04, stripHeight);
  const stripMat = new MeshBasicNodeMaterial({ color: colors.surface, transparent: true, opacity: 0.92 });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -height / 2 + stripHeight / 2, frontZ + 0.003);
  floatGroup.add(strip);

  const edgeGeo = new PlaneGeometry(width + 0.10, height + 0.10);
  const edgeMat = new MeshBasicNodeMaterial({ color: colors.accent, transparent: true, opacity: 0 });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = frontZ - 0.001;
  floatGroup.add(edge);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!tex) return;
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      const region = config.atlasRegion || config.intent?.visualSpec?.atlasRegion || null;
      if (region && tex.image) {
        tex.repeat.set(region.width / tex.image.width, region.height / tex.image.height);
        tex.offset.set(region.x / tex.image.width, region.y / tex.image.height);
      }
      picMat.map = tex;
      picMat.needsUpdate = true;
    }).catch(() => {});
  }

  const hoverTl = gsap.timeline({ paused: true })
    .to(floatGroup.position, { y: 0.15, duration: 0.8, ease: 'power2.out' });

  const pressTl = gsap.timeline({ paused: true })
    .to(floatGroup.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out' });

  const focusTl = gsap.timeline({ paused: true })
    .to(edgeMat, { opacity: 0.85, duration: 0.3, ease: 'power2.out' });

  let pressed = false;

  root.userData.handlers = {
    pointerenter() {
      hoverTl.play();
    },
    pointerleave() {
      hoverTl.reverse();
      if (pressed) {
        pressTl.reverse();
        pressed = false;
      }
    },
    pointerdown() {
      pressTl.play();
      pressed = true;
    },
    pointerup() {
      if (pressed) {
        pressTl.reverse();
        pressed = false;
      }
    },
    click() {
      ctx.emit('hub-journal.select', { id: config.id, target: 'hub-journal' });
    },
    focus() {
      focusTl.play();
      hoverTl.play();
    },
    blur() {
      focusTl.reverse();
      hoverTl.reverse();
    }
  };

  root.userData.dataBindings = [
    { source: 'form.email', target: 'trpc.waitlist.join.input.email' }
  ];

  root.userData.cleanup = function () {
    hoverTl.kill();
    pressTl.kill();
    focusTl.kill();

    backingGeo.dispose();
    backingMat.dispose();

    picGeo.dispose();
    if (picMat.map) picMat.map.dispose();
    picMat.dispose();

    stripGeo.dispose();
    stripMat.dispose();

    edgeGeo.dispose();
    edgeMat.dispose();
  };

  return root;
}
